INSERT INTO `BlogPost` (`id`, `title`, `slug`, `excerpt`, `contentHtml`, `featuredImage`, `imageAlt`, `authorName`, `status`, `scheduledAt`, `publishedAt`, `isFeatured`, `isDeleted`, `deletedAt`, `categoryId`, `tags`, `relatedPostIds`, `seoTitle`, `metaDescription`, `canonicalUrl`, `ogTitle`, `ogDescription`, `ogImage`, `noIndex`, `createdAt`, `updatedAt`) VALUES
(1, 'B2B Lead Generation in African Markets: The 2026 Strategy Playbook', 'b2b-lead-generation-africa-playbook', 'How forward-thinking companies are capturing high-growth opportunities across Nigeria, Kenya, Ghana, and South Africa.', '\n## Unlocking Africa\'s Rapidly Growing Digital Economy\n\nAfrica represents one of the fastest-growing digital commerce and technology markets globally. However, marketing strategies built exclusively for North American or European audiences frequently fail without local localization.\n\n### Key Factors for Success:\n1. **WhatsApp-First Conversion Funnels**: In many African business hubs, WhatsApp is not just a messaging app; it is the primary closing channel.\n2. **Local Payment Gateways**: Integrating Paystack, Flutterwave, and local banking options directly into your funnels drastically reduces checkout abandonment.\n3. **Local SEO & Community Networks**: Building genuine local authority requires localized search signals and African creator partnerships.\n\nAmplipath\'s dedicated Africa market division provides the local intelligence and execution necessary to scale across 15 African nations.\n', NULL, NULL, 'Amplipath Team', 'published', NULL, '2026-02-01 00:00:00', 0, 0, NULL, 2, NULL, NULL, 'B2B Lead Generation in African Markets: The 2026 Strategy Playbook', 'How forward-thinking companies are capturing high-growth opportunities across Nigeria, Kenya, Ghana, and South Africa.', NULL, 'B2B Lead Generation in African Markets: The 2026 Strategy Playbook', 'How forward-thinking companies are capturing high-growth opportunities across Nigeria, Kenya, Ghana, and South Africa.', '/images/logo-horizontal.jpg', 0, '2026-10-28 03:19:01', '2026-10-28 03:19:30'),
(2, 'Generative Engine Optimization: How to Rank in ChatGPT and Perplexity in 2026', 'generative-engine-optimization-guide', 'Discover the tactical roadmap for optimizing your brand for AI search engines, answer engines, and LLM-driven citation models.', '\n## The Rise of Answer Engine Optimization\n\nTraditional search engine optimization focused primarily on ten blue links on Google. Today, millions of users are turning directly to ChatGPT, Perplexity, Gemini, and Google AI Overviews for direct answers.\n\nIf your business is not structured for **Generative Engine Optimization (GEO)**, you risk becoming invisible to a rapidly growing segment of high-intent buyers.\n\n### 1. Structure Content for Direct Information Retrieval\n\nLarge Language Models (LLMs) prioritize content that:\n- Answers the core question directly in the first 50-70 words\n- Uses clean FAQ schemas and structured semantic tags\n- Demonstrates clear first-hand experience (E-E-A-T signals)\n\n### 2. Build Authoritative Entity Signals\n\nAI engines rely on consensus across trusted third-party datasets. Digital PR, high-authority mentions, and consistent structured citations teach AI models that your brand is the canonical answer in your industry.\n\n### 3. Track Share-of-Voice in AI Answers\n\nStart monitoring your brand\'s presence across major LLM queries weekly. Identify gaps where competitors are cited and systematically produce the citable content required to earn recommendations.\n', NULL, NULL, 'Amplipath Team', 'published', NULL, '2026-01-15 00:00:00', 0, 0, NULL, 1, NULL, NULL, 'Generative Engine Optimization: How to Rank in ChatGPT and Perplexity in 2026', 'Discover the tactical roadmap for optimizing your brand for AI search engines, answer engines, and LLM-driven citation models.', NULL, 'Generative Engine Optimization: How to Rank in ChatGPT and Perplexity in 2026', 'Discover the tactical roadmap for optimizing your brand for AI search engines, answer engines, and LLM-driven citation models.', '/images/logo-horizontal.jpg', 0, '2026-10-28 03:19:01', '2026-10-28 03:19:30'),
(3, 'Test', 'test', 'test', '<p>Start the new year with the evergreen resolution to lead a healthier lifestyle.</p><p>Here are 10 practical health tips to help you start off towards healthy living in 2025.</p><p><strong>1. Eat a healthy diet</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/eat-healthy.tmb-768v.jpg?sfvrsn=35008521_1" alt=""><p><em>Photo:&nbsp;WHO/ Y. Shimizu</em></p><p>Eat a combination of different foods, including fruit, vegetables, legumes, nuts and whole grains. Adults should eat at least five portions (400g) of fruit and vegetables per day. You can improve your intake of fruits and vegetables by always including veggies in your meal; eating fresh fruit and vegetables as snacks; eating a variety of fruits and vegetables; and eating them in season. By&nbsp;<a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://www.who.int/initiatives/behealthy/healthy-diet">eating healthy</a>, &nbsp;you will reduce your risk of malnutrition and noncommunicable diseases (NCDs) such as diabetes, heart disease, stroke and cancer.</p><p><strong>2. Consume less salt and sugar</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/reduce-salt.jpg?sfvrsn=11e77061_3" alt=""><p><em>Photo:&nbsp;WHO/C. Black</em></p><p>Reduce your salt intake to 5g per day, equivalent to about one teaspoon. It’s easier to do this by limiting the amount of salt, soy sauce, fish sauce and other high-sodium condiments when preparing meals; removing salt, seasonings and condiments from your meal table; avoiding salty snacks; and choosing low-sodium products.<br><br>On the other hand, consuming excessive amounts of sugars increases the risk of tooth decay and unhealthy weight gain. In both adults and children, the intake of free sugars should be reduced. WHO recommends consuming less than 5% of total energy intake for additional health benefits. You can reduce your sugar intake by limiting the consumption of sugary snacks, candies and sugar-sweetened beverages.</p><p><strong>3. Reduce intake of harmful fats</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/less-fats.jpg?sfvrsn=fde4b866_3" alt=""><p><em>Photo:&nbsp;WHO/S. Volkov</em></p><p>Fats consumed should be less than 30% of your total energy intake. This will help prevent unhealthy weight gain and NCDs. There are different types of fats, but unsaturated fats are preferable over saturated fats and trans-fats. WHO recommends reducing saturated fats to less than 10% of total energy intake; reducing trans-fats to less than 1% of total energy intake; and replacing both saturated fats and trans-fats with unsaturated fats.<br><br>The preferable unsaturated fats are found in fish, avocado and nuts, and in sunflower, soybean, canola and olive oils; saturated fats are found in fatty meat, butter, palm and coconut oil, cream, cheese, ghee and lard; and trans-fats are found in baked and fried foods, and pre-packaged snacks and foods, such as frozen pizza, cookies, biscuits, and cooking oils and spreads.</p><p><strong>4. Don’t smoke</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/smoking.jpg?sfvrsn=353d1892_3" alt=""><p><em>Photo:&nbsp;WHO/Y. Shimizu</em></p><p>Smoking tobacco causes NCDs such as lung disease, heart disease and stroke. Tobacco kills not only the direct smokers but even non-smokers through second-hand exposure.<br><br>If you are currently a smoker, it’s not too late to quit. Once you do, you will experience immediate and long-term&nbsp;<a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://www.who.int/news/item/02-07-2024-who-releases-first-ever-clinical-treatment-guideline-for-tobacco-cessation-in-adults">health benefits</a>. If you are not a smoker, that’s great! Do not start smoking and fight for your right to breathe tobacco-smoke-free air.</p><p><strong>5. Be active</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/physical-activity.jpg?sfvrsn=e54e8d67_4" alt=""><p><em>Photo:&nbsp;WHO/Y. Shimizu</em><br>Physical activity is defined as any bodily movement produced by skeletal muscles that requires energy expenditure. This includes exercise and activities undertaken while working, playing, carrying out household chores, travelling, and engaging in recreational pursuits. The amount of physical activity you need depends on your&nbsp;<a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://www.who.int/news-room/fact-sheets/detail/physical-activity">age group</a>&nbsp;but adults aged 18-64 years should do at least 150 minutes of moderate-intensity physical activity throughout the week. Increase moderate-intensity physical activity to 300 minutes per week for additional health benefits.</p><p><strong>6. Check your blood pressure regularly</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/ncd.tmb-768v.jpg?sfvrsn=14572a66_1" alt=""><p><em>Photo: WHO/Ahmad Yusni</em></p><p><a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://www.who.int/news-room/fact-sheets/detail/hypertension">Hypertension</a>, or high blood pressure, is called a “silent killer”. This is because many people who have hypertension may not be aware of the problem as it may not have any symptoms. If left uncontrolled, hypertension can lead to heart, brain, kidney and other diseases. Have your blood pressure checked regularly by a health worker so you know your numbers. If your blood pressure is high, get the advice of a health worker. This is vital in the prevention and control of hypertension.</p><p><strong>&nbsp;7. Follow traffic laws</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/follow-road-laws.jpg?sfvrsn=fb4f6a25_3" alt=""><p><em>Photo:&nbsp;WHO/D. Rodriguez</em><br>Road crashes claim over one million lives around the world and millions more are injured.&nbsp;<a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://www.who.int/news-room/fact-sheets/detail/road-traffic-injuries">Road traffic injuries</a>&nbsp;are preventable through a variety of measures implemented by the government such as strong legislation and enforcement, safer infrastructure and vehicle standards, and improved post-crash care. You yourself can also prevent road crashes by ensuring that you follow traffic laws such as using the seatbelt for adults and child restraint for your kids, wearing a helmet when riding a motorcycle or bicycle, not drinking and driving, and not using your mobile phone while driving.</p><p><strong>8. Take antibiotics only as prescribed</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/amr.jpg?sfvrsn=6b20050e_3" alt=""><p><em>Photo:&nbsp;WHO/F. Tanggol</em></p><p><a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://www.who.int/news-room/fact-sheets/detail/antibiotic-resistance">Antibiotic resistance</a>&nbsp;is one of the biggest public health threats in our generation. When antibiotics lose their power, bacterial infections become harder to treat, leading to higher medical costs, prolonged hospital stays, and increased mortality. Antibiotics are losing their power because of misuse and overuse in humans and animals. Make sure you only take antibiotics if prescribed by a qualified health professional. And once prescribed, complete the treatment days as instructed. Never share antibiotics.</p><p><strong>9. Clean your hands properly</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/hand-hygiene.jpg?sfvrsn=34b389a0_3" alt=""><p><em>Photo:&nbsp;WHO/S.Price</em></p><p>Hand hygiene is critical not only for health workers but for everyone. Clean hands can prevent the spread of infectious illnesses. You should&nbsp;<a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://cdn.who.int/media/docs/default-source/patient-safety/how-to-handwash-poster.pdf?sfvrsn=7004a09d_11">handwash using soap and water</a>&nbsp;when your hands are visibly soiled or&nbsp;<a target="_blank" rel="noopener noreferrer" class="text-blue-400 underline underline-offset-2 hover:text-blue-300 font-medium" href="https://cdn.who.int/media/docs/default-source/patient-safety/how-to-handrub-poster.pdf?sfvrsn=9d2f6e89_15">handrub using an alcohol-based product</a>.</p><p><strong>10. Have regular check-ups</strong></p><p></p><img class="rounded-xl max-w-full my-4 border border-slate-800 shadow-md" src="https://cdn.who.int/media/images/default-source/western-pacific-(wpro)/countries/malaysia/checkup.tmb-768v.jpg?sfvrsn=5aa16f38_1" alt=""><p><em>Photo:&nbsp;WHO/Y. Shimizu</em><br>Regular check-ups can help find health problems before they start. Health professionals can help find and diagnose health issues early, when your chances for treatment and cure are better. Go to your nearest health facility to check out the health services, screenings and treatment that are accessible to you.</p>', '/uploads/1793362650126_services-og.jpg', 'wow', 'Amplipath Team', 'published', '2026-10-30 12:18:00', '2026-10-30 12:19:19', 0, 1, '2026-10-31 02:30:22', 2, 'tag, tag', NULL, 'Test Article', 'wow tesr', NULL, 'wow', 'wow test', '/uploads/1793362726949_logo-horizontal.jpg', 0, '2026-10-30 12:19:19', '2026-10-31 02:30:22');
INSERT INTO `CaseStudy` (`id`, `name`, `slug`, `industry`, `headline`, `metric`, `metricLabel`, `summary`, `image`, `clientWebsite`, `appStoreUrl`, `playStoreUrl`, `overview`, `solution`, `results`, `services`, `deliverables`, `screenshots`, `keyStats`, `status`, `isFeatured`, `isDeleted`, `deletedAt`, `seoTitle`, `metaDescription`, `canonicalUrl`, `noIndex`, `ogTitle`, `ogDescription`, `ogImage`, `sortOrder`, `createdAt`, `updatedAt`) VALUES
(1, 'Amber’s Eternal', 'amber', 'Health, Beauty & Ecommerce', 'Full ecommerce development and technical SEO created a search-ready path from product discovery to checkout.', '+140%', 'Increase in organic website traffic', 'A complete ecommerce website and SEO foundation for a growing health and beauty brand, restructuring product discovery across 132+ items with a +90% conversion lift.', '/images/portfolio/amber.jpg', '', '', '', 'Amber’s Eternal is a health and beauty ecommerce brand offering essential oils, skincare, haircare, cosmetics, oil diffusers and other self-care products. The brand focuses on helping customers incorporate botanical-inspired wellness into their everyday routines.\n\nAmber’s Eternal needed more than an attractive online shop. Its broad product catalogue required a clear ecommerce structure that would help customers find suitable products while giving search engines a better understanding of the brand’s collections and individual product pages.', 'Designed and developed the complete ecommerce website from scratch, creating a scalable digital storefront for Amber’s Eternal.\n\nOrganised the catalogue into clear commercial categories covering essential oils, skincare, haircare, cosmetics, diffusers and beauty wellness.\n\nEngineered an extensive technical and on-page SEO framework covering crawlability, metadata, structured schema, and collection optimization.\n\nRefined the entire conversion journey from initial search discovery to product exploration and final checkout.', 'The completed website gave Amber’s Eternal a professional, scalable ecommerce presence supported by a stronger organic-search foundation.\n\nRecorded +140% growth in organic website search traffic within months of deployment.\n\nEcommerce conversion rate increased by +90% as navigation and checkout friction were eliminated across mobile and desktop.', '["Complete ecommerce website development","Mobile-responsive design","Product and collection architecture","Ecommerce navigation and user experience","Technical SEO & on-page optimization","Internal linking and metadata optimization","Conversion-focused shopping journey"]', '["Ecommerce Build","Technical SEO","On-Page SEO","CRO"]', '[]', '[{"label":"Live Products","value":"132+"},{"label":"Organic Traffic Lift","value":"+140%"},{"label":"Conversion Rate Lift","value":"+90%"}]', 'published', 1, 0, NULL, 'Amber’s Eternal Case Study | Amplipath', 'A complete ecommerce website and SEO foundation for a growing health and beauty brand, restructuring product discovery across 132+ items with a +90% conversion lift.', '', 0, '', '', '', 0, '2026-10-28 03:19:30', '2026-10-30 18:02:41'),
(2, 'Printin3D', 'print', '3D Printing & Ecommerce', 'Integrated Shopify, TikTok Shop and SEO launch generates 50%+ early sales growth.', '+400%', 'Increase in organic search traffic', 'A Shopify, TikTok Shop and SEO ecosystem for a specialist 3D-printing retailer—generating more than 50% early sales growth while building a stronger foundation for organic discovery.', '/images/portfolio/print.jpg', NULL, NULL, NULL, 'Printin3D is a specialist ecommerce store offering 3D printers, printing materials (PLA, PETG, TPU, resin), nozzles, hotends, tools and essential accessories. Its catalogue serves makers, educators, and industrial professionals.\n\nLaunching a specialist ecommerce business in the 3D-printing market required a platform capable of organising a technically diverse catalogue without making product discovery difficult, while driving sales beyond a single website channel.', 'Designed and developed the full Shopify store with structured navigation across printers, filaments, resins, and replacement components.\n\nIntegrated dropshipping fulfillment pipelines with automated catalog syncing and order routing.\n\nImplemented comprehensive technical and on-page SEO targeting high-intent commercial keywords across 3D-printing categories.\n\nBuilt and launched integrated TikTok Shop and Meta Shop storefronts to capture social commerce demand directly.', 'Recorded 50%+ early sales growth within the first days following multi-channel deployment.\n\nOrganic search traffic increased by +400% as category and product pages gained prominence across search engines.\n\nSuccessfully established 3 interconnected sales channels: Shopify Web, TikTok Shop, and Meta Shop.', '["Complete Shopify ecommerce development","Dropshipping catalogue setup & order routing","Product and collection architecture","TikTok Shop & Meta Shop integration","Technical & ecommerce SEO","Search-focused site structure"]', '["Shopify","TikTok Shop","Meta Shop","Dropship SEO"]', NULL, '[{"label":"Early Sales Growth","value":"50%+"},{"label":"Channels Launched","value":"3 Platforms"},{"label":"Organic Traffic Lift","value":"+400%"}]', 'published', 1, 0, NULL, 'Printin3D Case Study | Amplipath', 'A Shopify, TikTok Shop and SEO ecosystem for a specialist 3D-printing retailer—generating more than 50% early sales growth while building a stronger foundation for organic discovery.', NULL, 0, NULL, NULL, NULL, 1, '2026-10-28 03:19:30', '2026-10-28 03:19:30'),
(3, 'Furry Fiesta', 'furry', 'Pet Accessories & Ecommerce', 'Conversion-focused ecommerce redesign delivers a 250%+ increase in store conversions.', '+250%', 'Increase in ecommerce conversions', 'A complete ecommerce redesign that improved product discovery, simplified the buying journey and helped turn more store visitors into customers.', '/images/portfolio/furry.jpg', NULL, NULL, NULL, 'Furry Fiesta is an online pet-accessories retailer offering pet beds, grooming brushes, collars, feeding bowls, toys and everyday pet essentials designed to combine comfort, functionality, safety and style.\n\nFurry Fiesta needed a more cohesive ecommerce experience capable of turning product interest into completed purchases. Product discovery, navigation, page hierarchy and calls to action all needed to work together as one conversion-focused shopping system.', 'Restructured the entire storefront experience around how pet owners discover, evaluate and purchase essentials.\n\nRefreshed the visual presentation, strengthened page hierarchy, and created clearer pathways from homepage to product pages.\n\nPositioned product information and CTAs to reduce friction and guide shoppers intuitively toward checkout.\n\nOptimised the responsive mobile layout to ensure lightning-fast performance across all mobile devices.', 'Delivered a verified 250%+ increase in completed store conversions from existing traffic.\n\nSignificantly reduced checkout abandonment and improved multi-item cart values.\n\nPreserved the friendly brand personality while providing a robust, commercially engineered digital storefront.', '["Complete ecommerce store redesign","Product and collection-page optimisation","Navigation and customer-journey restructuring","Mobile-responsive design","Calls-to-action optimisation","Ecommerce conversion-rate optimisation"]', '["Store Redesign","CRO","Mobile Responsiveness","UX Design"]', NULL, '[{"label":"Conversion Lift","value":"+250%"},{"label":"Mobile Checkout Speed","value":"<1.8s"},{"label":"Navigation Friction","value":"-65%"}]', 'published', 1, 0, NULL, 'Furry Fiesta Case Study | Amplipath', 'A complete ecommerce redesign that improved product discovery, simplified the buying journey and helped turn more store visitors into customers.', NULL, 0, NULL, NULL, NULL, 2, '2026-10-28 03:19:30', '2026-10-28 03:19:30'),
(4, 'Olakunle & Partners Ltd', 'ola', 'Real Estate & Property Investment', 'A conversion-ready real estate website produces an 80%+ increase in property enquiries.', '+80%', 'Increase in property enquiries', 'A complete real estate website that transformed property discovery into a clearer, more credible and conversion-focused enquiry experience.', '/images/portfolio/ola.jpg', NULL, NULL, NULL, 'Olakunle & Partners Ltd is a Nigerian real estate and property investment company providing property sales, rentals, facility management, estate development and advisory services for individuals and institutional investors.\n\nThe company required a credible digital platform where potential clients could understand its services, explore available properties and quickly express interest matching their budget, preferred location and property requirements.', 'Planned information architecture and developed a modern, high-speed responsive real estate web platform.\n\nOrganised available properties into clear categories including sales, rentals, and commercial estate developments.\n\nImplemented structured enquiry pathways allowing prospective clients to submit their budget, location, and property criteria.\n\nIntegrated direct WhatsApp and phone consultation pathways to capture high-intent buyers immediately.', 'Generated an 80%+ increase in verified property enquiries across residential and commercial opportunities.\n\nEstablished a credible digital presence that elevated the firm\'s authority among high-net-worth investors.\n\nCreated a scalable foundation for listing new developments and capturing ongoing buyer leads.', '["Website strategy and information architecture","Responsive website development","Property listing and category structure","Lead-generation form development","WhatsApp and contact-path integration","Conversion-path optimisation"]', '["Website Build","Property Listings","Lead Generation","WhatsApp Routing"]', NULL, '[{"label":"Enquiry Growth","value":"+80%"},{"label":"WhatsApp Leads","value":"3.4x"},{"label":"Listing Engagement","value":"+120%"}]', 'published', 0, 0, NULL, 'Olakunle & Partners Ltd Case Study | Amplipath', 'A complete real estate website that transformed property discovery into a clearer, more credible and conversion-focused enquiry experience.', NULL, 0, NULL, NULL, NULL, 3, '2026-10-28 03:19:30', '2026-10-28 03:19:30'),
(5, 'Forbidden Touch', 'forbidden', 'Beauty, Spa & Wellness', 'Complete SEO optimisation achieves a 96% performance score and an A-grade website experience.', '96%', 'Performance score & Grade A experience', 'A complete SEO and website-performance programme that delivered an A-grade experience, 1.2-second main-content loading and excellent visual stability.', '/images/portfolio/forbidden.jpg', NULL, NULL, NULL, 'Forbidden Touch was a beauty, wellness and body-spa brand created to provide customers with a relaxing digital experience that reflected the comfort and quality of its services.\n\nFor a wellness business, slow loading, poor structure or weak on-page signals create immediate bounce-offs. The SEO engagement needed to improve technical performance, page hierarchy, and search accessibility simultaneously.', 'Conducted a comprehensive technical SEO review covering Core Web Vitals, server responsiveness, and asset delivery.\n\nOptimised image payloads, asset minification, and browser caching to achieve sub-1.5s page load times.\n\nRestructured heading tags, metadata, and on-page content around local wellness and spa search queries.\n\nEliminated layout shifts and blocking scripts to provide a perfectly stable, tranquil browsing environment.', 'Achieved a 96% GTmetrix performance score and 98% website structure score.\n\nRecorded a rapid 1.2-second Largest Contentful Paint (LCP) and minimal 59ms Total Blocking Time.\n\nAttained a Cumulative Layout Shift (CLS) of 0.02, delivering flawless visual stability across devices.', '["Complete website SEO","Technical SEO audit and implementation","On-page content optimisation","Page-speed optimisation & asset minification","Core Web Vitals remediation","Mobile and desktop performance review"]', '["Technical SEO","Core Web Vitals","PageSpeed","On-Page SEO"]', NULL, '[{"label":"GTmetrix Grade","value":"Grade A"},{"label":"Performance Score","value":"96%"},{"label":"Largest Contentful Paint","value":"1.2s"},{"label":"Total Blocking Time","value":"59ms"}]', 'published', 0, 0, NULL, 'Forbidden Touch Case Study | Amplipath', 'A complete SEO and website-performance programme that delivered an A-grade experience, 1.2-second main-content loading and excellent visual stability.', NULL, 0, NULL, NULL, NULL, 4, '2026-10-28 03:19:30', '2026-10-28 03:19:30'),
(6, 'Savajay', 'savajay', 'Cannabis Accessories & Specialist Ecommerce', 'Complete SEO implementation achieves an excellent 96/100 website health score.', '96/100', 'Excellent website health score', 'Complete technical and on-page SEO for a specialist ecommerce product, resulting in 127 error-free URLs, 130 successful HTTP responses and a search-ready website structure.', '/images/portfolio/savajay.jpg', NULL, NULL, NULL, 'Savajay is a specialist product brand offering a compact, portable device designed to extinguish and smell-proof store partially used joints and smoking items.\n\nBecause the product represents a highly specialised niche, potential buyers search using varied terms (e.g., \'joint extinguisher\', \'joint storage case\', \'smell-proof joint holder\'). The SEO strategy had to unite these terms and ensure flawless search engine crawlability.', 'Conducted thorough keyword mapping and mapped search intent across product titles, descriptions, and headings.\n\nStructured the homepage with one clear H1 supported by 7 H2 and 6 H3 subheadings for optimal topical hierarchy.\n\nConfigured canonical tags, XML sitemaps, robots.txt directives, and clean internal link structures.\n\nAudited all HTTP status codes, resolving redirect chains and eliminating broken assets across the domain.', 'Achieved an outstanding 96/100 overall technical website health score on comprehensive audit tools.\n\nVerified 127 URLs completely free of errors with 130 clean 2xx responses and canonical tags detected.\n\nPositioned the specialist product prominently for diverse commercial search phrases across its category.', '["Complete website SEO audit","Technical SEO remediation","Keyword research and mapping","Heading and content hierarchy optimisation","Canonical URL and directive configuration","Crawlability and indexation optimisation"]', '["Site Audit","Technical SEO","Keyword Architecture","Indexation"]', NULL, '[{"label":"Site Health Score","value":"96 / 100"},{"label":"Error-Free URLs","value":"127 URLs"},{"label":"Clean HTTP 200s","value":"130 Responses"}]', 'published', 0, 0, NULL, 'Savajay Case Study | Amplipath', 'Complete technical and on-page SEO for a specialist ecommerce product, resulting in 127 error-free URLs, 130 successful HTTP responses and a search-ready website structure.', NULL, 0, NULL, NULL, NULL, 5, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(7, 'Zarea — B2B Commodity Marketplace Website', 'zarea-web', 'B2B Ecommerce, Commodities & Procurement', 'A digital marketplace connecting commodity buyers and suppliers across Pakistan.', 'B2B Commerce', 'Quotations, accounts & multi-category catalogue', 'A B2B ecommerce marketplace combining product categories, supplier access, quotation requests, customer accounts, and shopping-cart functionality built for business procurement.', '/images/portfolio/zarea-web.png', NULL, NULL, NULL, 'Zarea is a B2B ecommerce marketplace designed to make commodity sourcing faster and more accessible for commercial enterprises.\n\nEnterprise buyers and institutional suppliers require comprehensive product documentation, bulk pricing structures, and quotation workflows that mirror real-world corporate purchasing procedures.', 'Architected and developed the responsive web platform tailored specifically for business procurement.\n\nCombined product categories, supplier access, quotation requests (RFQs), customer accounts, and shopping-cart functionality.\n\nEngineered corporate information hubs, transaction safeguards, and high-volume catalogue navigation.\n\nOptimized technical performance and search visibility across all core commodity sectors.', 'Delivered a dependable digital marketplace handling substantial commercial transaction inquiry volume.\n\nEstablished brand credibility with corporate institutional clients and manufacturing leaders.\n\nStreamlined supplier onboarding and quotation management across diverse commodity categories.', '["Full-stack B2B marketplace development","Product category and catalogue architecture","Quotation and customer account workflows","Enterprise UI/UX design","Technical SEO and platform performance"]', '["Web Platform","B2B Ecommerce","Catalogue Architecture","Enterprise UX"]', NULL, '[{"label":"Platform Type","value":"B2B Web Marketplace"},{"label":"Commerce Tools","value":"RFQ & Cart Engine"},{"label":"Experience","value":"Responsive Desktop & Mobile"}]', 'published', 0, 0, NULL, 'Zarea — B2B Commodity Marketplace Website Case Study | Amplipath', 'A B2B ecommerce marketplace combining product categories, supplier access, quotation requests, customer accounts, and shopping-cart functionality built for business procurement.', NULL, 0, NULL, NULL, NULL, 6, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(8, 'Cursos Online GIS', 'cursos-online-gis', 'E-Learning, GIS & Drone Technology', 'Comprehensive on-page and off-page SEO strategy expanded organic search visibility and course enrollments for a specialized geospatial training platform.', '+185%', 'Increase in organic search impressions', 'Implemented a complete on-page and off-page SEO strategy—including in-depth keyword research, metadata optimization, structured data implementation, technical SEO enhancements, and authoritative off-page backlink development to improve visibility and search rankings.', '/images/portfolio/cursos-online-gis.png', 'https://cursosonlinegis.com/', NULL, NULL, 'Cursos Online GIS is a premier Spanish-language online training academy providing specialized professional instruction in Geographic Information Systems (GIS), drone topography, remote sensing, and geospatial mapping tools for engineers, cartographers, surveyors, and environmental consultants.\n\nDespite producing industry-leading curriculum in drone topography and specialized GIS software, Cursos Online GIS faced competitive organic search hurdles. The platform required a comprehensive keyword taxonomy, structured course schema, elimination of technical indexing bottlenecks, and authoritative off-page backlink development to secure first-page rankings across targeted Spanish-language searches.', 'Conducted in-depth keyword research across geospatial, drone surveying, and GIS software search verticals to identify high-intent commercial course queries.\n\nOptimized all on-page metadata, header hierarchies, image alt tags, and course landing page copy for targeted keyword clusters.\n\nImplemented advanced Schema.org Course, Organization, and FAQ structured data markup to capture rich search snippets on Google.\n\nAudited and resolved technical SEO issues, streamlining site architecture, canonicalization, crawl depth, and mobile page experience.\n\nExecuted an authoritative off-page SEO and digital PR strategy, securing high-relevance contextual backlinks within surveying, engineering, and tech domains.', 'Achieved a +185% increase in total organic search visibility and impressions within six months of optimization.\n\nSecured top-3 Google rankings for high-value competitive terms including \'topografía con drones\' and primary GIS course keywords.\n\nDelivered a +75% lift in direct organic student enrollments while decreasing reliance on paid advertising.', '["Comprehensive Keyword Research & Search Intent Mapping","Technical SEO Audit & Architecture Remediation","On-Page Content, Heading & Metadata Optimization","Schema.org Course & FAQ Structured Data","Off-Page SEO & Authority Backlink Acquisition","Mobile Experience & Core Web Vitals Optimization"]', '["On-Page SEO","Technical SEO","Keyword Strategy","Structured Data","Off-Page SEO"]', NULL, '[{"label":"Organic Impressions","value":"+185%"},{"label":"Top-3 Search Rankings","value":"45+"},{"label":"Course Enrollment Lift","value":"+75%"}]', 'published', 0, 0, NULL, 'Cursos Online GIS Case Study | Amplipath', 'Implemented a complete on-page and off-page SEO strategy—including in-depth keyword research, metadata optimization, structured data implementation, technical SEO enhancements, and authoritative off-page backlink development to improve visibility and search rankings.', NULL, 0, NULL, NULL, NULL, 7, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(9, 'Lifted High Garage Door Repair', 'lifted-high-garage-doors', 'Home Services & Local Contracting', 'Technical SEO, site architecture, and Core Web Vitals optimization unlocked top local search rankings and high-intent repair bookings.', '+210%', 'Increase in local organic leads & calls', 'A comprehensive local and technical SEO overhaul for an Arizona garage door service company—optimizing on-page content, site structure, mobile speed, and LocalBusiness schema markup to dominate high-intent local search queries across Maricopa and surrounding areas.', '/images/portfolio/lifted-high-garage-doors.png', 'https://liftedhighgaragedoors.com/', NULL, NULL, 'Lifted High Garage Doors (A Triple B Company) is a licensed, bonded, and insured residential and commercial garage door contractor serving Maricopa, Casa Grande, Chandler, Ahwatukee, and Sun Lakes, Arizona. They specialize in same-day emergency repairs, broken spring replacements, opener installations, and new door fitments.\n\nOperating in a highly competitive regional home services market, Lifted High required more than basic directory listings to compete with national franchises. The website suffered from slow mobile loading speeds, missing structured data, unoptimized local landing pages, and disjointed navigation that hindered organic search engines from accurately associating their services with their expanding Arizona service territory.', 'Conducted a comprehensive technical and structural audit to organize service silos and dedicated geo-landing pages across Maricopa, Casa Grande, Chandler, Ahwatukee, and Sun Lakes.\n\nOptimized on-page SEO targeting high-intent emergency repair and installation keywords across all page titles, headings, and body copy.\n\nImplemented comprehensive LocalBusiness, Service, and FAQ Schema.org structured data to enable rich Google search features and geographic entity verification.\n\nExecuted aggressive Core Web Vitals and page speed optimizations, optimizing image assets, script loading, and caching to achieve sub-second mobile render times.\n\nRefined user conversion pathways and call-to-action triggers (\'Request an Estimate\' and direct click-to-call) to maximize mobile lead conversion rates.', 'Achieved a +210% increase in local organic search visibility and direct phone call inquiries across core Arizona service areas.\n\nElevated mobile Google PageSpeed score to 98/100, dramatically cutting bounce rates from paid and organic visitors.\n\nSecured top-3 local organic rankings for critical commercial terms including \'garage door repair Maricopa\' and \'broken spring replacement\'.', '["Technical SEO Audit & Structural Optimization","Local Keyword Research & Geo-Targeting Strategy","On-Page Content & Metadata Hierarchy Optimization","Schema.org LocalBusiness & Service Structured Data","Core Web Vitals & Page Speed Acceleration","Mobile Conversion Rate Optimization (CRO)"]', '["Local SEO","Technical SEO","Site Architecture","Schema Markup","Page Speed Optimization"]', NULL, '[{"label":"Local Search Visibility","value":"+210%"},{"label":"Mobile Page Speed","value":"98 / 100"},{"label":"Service Area Rankings","value":"Top 3"}]', 'published', 0, 0, NULL, 'Lifted High Garage Door Repair Case Study | Amplipath', 'A comprehensive local and technical SEO overhaul for an Arizona garage door service company—optimizing on-page content, site structure, mobile speed, and LocalBusiness schema markup to dominate high-intent local search queries across Maricopa and surrounding areas.', NULL, 0, NULL, NULL, NULL, 8, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(10, 'Ace of Coins', 'aceofcoins', 'Online Education & Digital Courses', 'Two conversion-focused course funnels generate 8,759 page views and a 35%+ conversion rate.', '35%+', 'Funnel conversion rate (8,759 page views)', 'Two purpose-built course funnels designed to turn specialised educational offers into focused, measurable conversion journeys.', '/images/portfolio/aceofcoins.jpg', NULL, NULL, NULL, 'Ace of Coins is an online learning platform offering specialist paid educational courses, video lessons, and digital resources for professionals and learners worldwide.\n\nGeneral catalog pages dilute focus for specialized course offers. Ace of Coins required dedicated, persuasive funnel pages capable of guiding visitors through course value, addressing objections, and converting interest into paid enrollments.', 'Developed dedicated, high-converting sales funnels for individual course titles including \'Cryptos Are Not Taxable\' and \'Divorcing the State\'.\n\nOrganised course curriculum into a clear, persuasive hierarchy highlighting student benefits, instructor credibility, and objection handling.\n\nConstructed fast, mobile-first layouts with conversion-optimized CTAs and minimal checkout friction.\n\nIntegrated full-funnel tracking to measure traffic sources, scroll depths, and conversion completion.', 'Recorded 8,759 page views with an extraordinary tracked conversion rate exceeding 35%.\n\nCreated an independent sales engine allowing course offers to be marketed via paid and organic channels with predictable ROI.\n\nProvided Ace of Coins with a proven template for rolling out future digital course launches.', '["Sales-funnel strategy & architecture","Conversion landing-page design & development","Calls-to-action & offer positioning","Responsive mobile development","Traffic and conversion event tracking"]', '["Sales Funnels","Landing Pages","Conversion Strategy","Analytics"]', NULL, '[{"label":"Page Views Tracked","value":"8,759"},{"label":"Tracked Conversion Rate","value":"35%+"},{"label":"Funnels Built","value":"2 Custom Journeys"}]', 'published', 0, 0, NULL, 'Ace of Coins Case Study | Amplipath', 'Two purpose-built course funnels designed to turn specialised educational offers into focused, measurable conversion journeys.', NULL, 0, NULL, NULL, NULL, 9, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(11, 'Act or Pass', 'actorpass', 'Games, Entertainment & Ecommerce', 'Multichannel promotion drives 700% website traffic growth and more than 19,000 YouTube views.', '+700%', 'Website traffic growth & 19K+ video views', 'A multichannel promotional campaign combining Reddit, forums, classified advertising, social media and YouTube to generate 24,845 impressions and a reported conversion rate above 75%.', '/images/portfolio/actorpass.jpg', NULL, NULL, NULL, 'Act or Pass is a movie-inspired party card game that brings friends, families and colleagues together through acting, film trivia and creative communication.\n\nAs a novel physical card game sold online, Act or Pass needed more than standard ads. Potential buyers needed to understand the fun of playing the game, see it demonstrated visually, and be engaged within entertainment communities.', 'Executed targeted Reddit and forum marketing in active movie, gaming, and entertainment sub-communities.\n\nProduced and distributed engaging YouTube video demonstrations showcasing authentic gameplay and player reactions.\n\nIntegrated classified advertising and social media campaigns to direct interested players straight to the online shop.\n\nBuilt a seamless path connecting organic video views directly to the ecommerce purchase funnel.', 'Generated 24,845 campaign impressions and delivered a +700% surge in website traffic.\n\nAchieved over 19,000 YouTube video views with high engagement from entertainment enthusiasts.\n\nRecorded a reported campaign conversion rate exceeding 75% on targeted landing experiences.', '["Digital growth strategy","Reddit and forum community marketing","Classified advertising campaigns","Social media promotion","YouTube video marketing & distribution","Conversion-path optimisation"]', '["Reddit Marketing","YouTube Marketing","Social Media","Community Seeding"]', NULL, '[{"label":"Traffic Growth","value":"+700%"},{"label":"YouTube Views","value":"19,000+"},{"label":"Reported Conversion","value":"75%+"},{"label":"Campaign Impressions","value":"24,845"}]', 'published', 0, 0, NULL, 'Act or Pass Case Study | Amplipath', 'A multichannel promotional campaign combining Reddit, forums, classified advertising, social media and YouTube to generate 24,845 impressions and a reported conversion rate above 75%.', NULL, 0, NULL, NULL, NULL, 10, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(12, 'DaVinci Resolve Mastery', 'davinci', 'Online Education & Video Production', 'Targeted course promotion delivers +9,009% student growth and +21,084% more ratings.', '+9,009%', 'Student growth (564 to 51,373 enrolled)', 'A targeted course promotion campaign that scaled student enrolment from 564 to 51,373 and grew ratings to 9,533 while sustaining a strong 4.6-star rating.', '/images/portfolio/davinci.jpg', NULL, NULL, NULL, 'This comprehensive video editing course teaches aspiring filmmakers and editors DaVinci Resolve—from fundamentals to advanced colour grading, audio post-production, and visual effects.\n\nAt the start of the engagement, the course had 564 students and 45 ratings. Despite excellent content, it lacked the marketplace search momentum and social proof needed to compete against entrenched video editing courses.', 'Optimised course metadata, keywords, and title structures for marketplace search algorithms.\n\nRan targeted promotional campaigns attracting relevant video creators, editors, and hobbyists.\n\nImplemented review and rating acquisition sequences that converted enrolled learners into active reviewers.\n\nEstablished multi-channel promotional funnels that fed continuous new enrollments into the course.', 'Student enrolment scaled from 564 to 51,373—representing a monumental +9,009% increase.\n\nRating volume expanded from 45 to 9,533 verified reviews—a +21,084% increase.\n\nSustained an outstanding 4.6-star student satisfaction rating throughout rapid scale.', '["Course promotion & marketplace SEO","Targeted paid learner acquisition","Social proof & rating generation workflow","Audience segmentation & creative strategy","Continuous conversion monitoring"]', '["Course Promotion","Marketplace SEO","Paid Acquisition","Social Proof"]', NULL, '[{"label":"Students Enrolled","value":"564 → 51,373"},{"label":"Student Growth","value":"+9,009%"},{"label":"Rating Volume","value":"45 → 9,533 (+21,084%)"},{"label":"Course Rating","value":"4.6 Stars"}]', 'published', 0, 0, NULL, 'DaVinci Resolve Mastery Case Study | Amplipath', 'A targeted course promotion campaign that scaled student enrolment from 564 to 51,373 and grew ratings to 9,533 while sustaining a strong 4.6-star rating.', NULL, 0, NULL, NULL, NULL, 11, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(13, 'Pitch Yourself! (Alexa Fischer)', 'alexafischer', 'Professional & Personal Development', 'Growth campaign generates +4,317% student growth and +11,087% more ratings.', '+4,317%', 'Student growth (834 to 36,834 enrolled)', 'A targeted growth campaign that increased course discovery, attracted 36,000+ relevant learners, and generated over 10,000 positive ratings while maintaining a 4.5-star rating.', '/images/portfolio/alexafischer.jpg', NULL, NULL, NULL, 'Pitch Yourself! is an acclaimed personal-development course created by executive coach Alexa Fischer, designed to help professionals, entrepreneurs, and speakers communicate with clarity, confidence, and authenticity.\n\nPrior to our campaign, the course had 834 students and 92 ratings. The objective was to expand course visibility globally, reach professionals seeking presentation confidence, and establish category dominance.', 'Refined course keywords, titles, and curriculum previews to align with professional communication search queries.\n\nLaunched multi-channel promotional campaigns targeting professionals, founders, and career-switchers.\n\nCreated an automated student engagement and review workflow to drive high rating velocity.\n\nMaintained aggressive marketplace category positioning to trigger algorithm recommendations.', 'Student enrolment increased from 834 to 36,834—delivering a massive +4,317% growth.\n\nReview count grew from 92 to 10,292 verified ratings—an extraordinary +11,087% expansion.\n\nMaintained a stellar 4.5-star overall rating while becoming one of the most recommended public speaking courses.', '["Course marketing & marketplace algorithm strategy","Targeted professional learner acquisition","Social proof and review generation engine","Campaign performance tracking & scaling"]', '["Course Growth","Audience Expansion","Marketplace SEO","Reviews"]', NULL, '[{"label":"Enrolled Students","value":"834 → 36,834"},{"label":"Student Growth","value":"+4,317%"},{"label":"Rating Volume","value":"92 → 10,292 (+11,087%)"},{"label":"Average Rating","value":"4.5 Stars"}]', 'published', 0, 0, NULL, 'Pitch Yourself! (Alexa Fischer) Case Study | Amplipath', 'A targeted growth campaign that increased course discovery, attracted 36,000+ relevant learners, and generated over 10,000 positive ratings while maintaining a 4.5-star rating.', NULL, 0, NULL, NULL, NULL, 12, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(14, 'Novella AI', 'novella', 'AI, SaaS & Video Technology', 'Integrated investor outreach helps Novella AI nearly triple its Wefunder raise to $349,494.', '$349,494', 'Raised on Wefunder (+200% funding growth)', 'A multichannel investor-acquisition campaign delivered through Boostfunders that helped Novella AI progress from $116,509 to $349,494 and grow its investor community from 83 to 162.', '/images/portfolio/novella.jpg', NULL, NULL, NULL, 'Novella AI is an advanced AI-powered video editing software developed by industry veterans with deep Hollywood and tech backgrounds (Apple, Adobe, Google), built to redefine creative video post-production.\n\nNovella AI had raised an initial $116,509 from 83 investors on Wefunder. To maintain momentum and reach its expansion milestones, the company needed a strategic push to introduce the opportunity to accredited and retail tech investors outside its immediate network.', 'Deployed Boostfunders\' equity crowdfunding framework combining direct investor outreach, social media, and community engagement.\n\nTargeted relevant tech founder forums, creative video communities, and retail investor syndicates.\n\nCrafted compelling campaign positioning highlighting the founding team\'s Hollywood pedigree and AI architecture.\n\nMonitored momentum daily, actively engaging prospective backers and addressing questions on the Wefunder platform.', 'The campaign added $232,985 in fresh capital, progressing from $116,509 to a final raise of $349,494.\n\nTotal funds raised surged by approximately 200%—finishing with almost three times its starting funding total.\n\nExpanded the investor community from 83 to 162 backers, achieving a 95.2% increase in participating investors.', '["Equity crowdfunding marketing","Direct investor outreach & engagement","Social media marketing & distribution","Community and tech forum promotion","Campaign positioning & messaging support","Multichannel promotional strategy"]', '["Equity Crowdfunding","Investor Outreach","Social Promotion","PR"]', NULL, '[{"label":"Total Raised","value":"$349,494"},{"label":"Capital Added","value":"+$232,985"},{"label":"Fundraising Growth","value":"+200%"},{"label":"Investor Count","value":"83 → 162 (+95.2%)"}]', 'published', 0, 0, NULL, 'Novella AI Case Study | Amplipath', 'A multichannel investor-acquisition campaign delivered through Boostfunders that helped Novella AI progress from $116,509 to $349,494 and grow its investor community from 83 to 162.', NULL, 0, NULL, NULL, NULL, 13, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(15, 'Thimin — AI Life Coach', 'thimin', 'AI, Wellness & Personal Development', 'An AI-powered life coach built to support personal growth through natural voice conversations.', 'Voice AI', 'Real-time conversational coaching', 'A cross-platform AI life-coaching app for iOS and Android combining natural voice conversations, transcription, session summaries, journaling and goal tracking.', '/images/portfolio/thimin.png', NULL, NULL, NULL, 'Thimin is an innovative wellness and personal development application designed to help individuals incorporate mindful self-reflection and personal growth into everyday life.\n\nTraditional coaching and journaling tools require manual typing or rigid scheduling. Thimin required an intuitive mobile experience where users could speak naturally, receive thoughtful contextual reflections, and track their personal growth over time without friction.', 'Designed and developed the cross-platform mobile application for iOS and Android.\n\nEngineered low-latency voice-based AI conversations with contextual responses and adaptive empathy.\n\nBuilt automated real-time speech-to-text transcription and structured session summary generation.\n\nImplemented personal journaling, daily reflection prompts, and habit/goal-tracking workflows within one accessible mobile experience.', 'Successfully launched an intuitive, highly engaging cross-platform coaching experience with high user retention.\n\nDelivered instant voice AI interaction with zero audio lag across mobile networks.\n\nProvided users with an organized personal knowledge base of past reflections, insights, and milestones.', '["Mobile app development (iOS & Android)","Voice AI integration & prompt engineering","Real-time audio streaming & transcription","Session summarization engine","App Store & Google Play deployment"]', '["Mobile App","Voice AI","iOS & Android","Personal Development"]', NULL, '[{"label":"Supported Platforms","value":"iOS & Android"},{"label":"Core Interface","value":"Natural Voice AI"},{"label":"Key Features","value":"Journaling & Goals"}]', 'published', 0, 0, NULL, 'Thimin — AI Life Coach Case Study | Amplipath', 'A cross-platform AI life-coaching app for iOS and Android combining natural voice conversations, transcription, session summaries, journaling and goal tracking.', NULL, 0, NULL, NULL, NULL, 14, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(16, 'Peony Bloom — Couples Game', 'peony', 'Lifestyle, Relationships & Mobile Gaming', 'A private couples game designed to create more meaningful and playful conversations.', 'Private Pairing', 'Simultaneous response reveals', 'A cross-platform couples game where partners connect privately, answer questions separately and reveal responses together across multiple conversation modes.', '/images/portfolio/peony.png', NULL, NULL, NULL, 'Peony Bloom is a mobile lifestyle and gaming experience created to help couples build intimacy, have fun, and engage in meaningful conversations.\n\nCouples often struggle to initiate fresh, playful conversations amidst busy schedules. The app needed a private, delightful interface that made vulnerability fun through game mechanics rather than clinical exercises.', 'Architected cross-platform mobile apps for iOS and Android with real-time pairing via secure invite codes.\n\nEngineered synchronized question-and-answer mechanics where responses remain hidden until both partners answer.\n\nCreated curated question decks across intimacy, fun memories, future aspirations, and playful debates.\n\nIntegrated turn push notifications, saved favorite moments, and premium subscription access via App Store & Play Store in-app purchases.', 'Delivered an engaging, highly rated mobile experience for couples globally.\n\nAchieved seamless real-time synchronization between paired devices without connection drops.\n\nEstablished recurring subscription revenue with high deck completion rates.', '["Cross-platform mobile app development","Real-time partner synchronization backend","Interactive UI/UX design & animation","In-app purchase & subscription management","Push notification workflows"]', '["Mobile Gaming","iOS & Android","Relationship Tech","In-App Subscriptions"]', NULL, '[{"label":"Supported Platforms","value":"iOS & Android"},{"label":"Interaction Model","value":"Private Pairing"},{"label":"Monetization","value":"Subscriptions & Decks"}]', 'published', 0, 0, NULL, 'Peony Bloom — Couples Game Case Study | Amplipath', 'A cross-platform couples game where partners connect privately, answer questions separately and reveal responses together across multiple conversation modes.', NULL, 0, NULL, NULL, NULL, 15, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(17, 'Fresenius Kabi Enteral App', 'fresenius', 'Healthcare & Medical Technology', 'A mobile product and nutritional-reference platform built for healthcare professionals.', 'HCP Platform', 'Product compendium & RNI comparison', 'A mobile product and nutritional-reference platform delivering adult and paediatric enteral nutrition product information, clinical resources, and PDF export functionality.', '/images/portfolio/fresenius.png', NULL, NULL, NULL, 'Fresenius Kabi is a global healthcare leader specializing in clinical nutrition, infusion therapies, and lifesaving medical products.\n\nHealthcare professionals require rapid, accurate nutritional specifications when recommending adult and paediatric enteral nutrition solutions. The app needed to provide immediate, compliant access to comprehensive product compendiums and reference calculations.', 'Delivered the iOS and Android application experience for accessing Fresenius Kabi\'s adult and paediatric enteral nutrition product information.\n\nEngineered an interactive product compendium and healthcare-professional registration system.\n\nBuilt a dynamic Reference Nutrient Intake (RNI) comparison tool and clinical resource library.\n\nIntegrated seamless patient sample requests and one-click PDF export functionality.', 'Equipped medical professionals with an essential daily bedside clinical calculator and formula compendium.\n\nAccelerated institutional sample request turnaround and improved nutritional prescription accuracy.\n\nDelivered a dependable digital resource recognized for speed, reliability, and clinical utility.', '["Mobile application development (iOS & Android)","Clinical product compendium architecture","RNI comparison tool engineering","Patient sample request integration","PDF export & clinical documentation"]', '["HealthTech","Clinical App","Nutritional Calculator","PDF Export"]', NULL, '[{"label":"Target Audience","value":"Healthcare Professionals"},{"label":"Platforms","value":"iOS & Android"},{"label":"Key Tool","value":"RNI Comparison"}]', 'published', 0, 0, NULL, 'Fresenius Kabi Enteral App Case Study | Amplipath', 'A mobile product and nutritional-reference platform delivering adult and paediatric enteral nutrition product information, clinical resources, and PDF export functionality.', NULL, 0, NULL, NULL, NULL, 16, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(18, 'Zarea — B2B Marketplace Mobile App', 'zarea-app', 'B2B Ecommerce, Commodities & Procurement', 'A cross-platform B2B marketplace simplifying commodity sourcing and procurement.', 'Mobile B2B', 'End-to-end commodity procurement', 'A cross-platform B2B marketplace enabling businesses to source construction materials, agricultural products, industrial chemicals and commodities with live delivery tracking.', '/images/portfolio/zarea-app.png', NULL, NULL, NULL, 'Zarea is a cross-platform B2B marketplace that enables businesses to source construction materials, agricultural products, industrial chemicals and other commodities.\n\nTraditional commodity sourcing involves disjointed broker negotiations and manual coordination. Zarea needed a unified mobile experience enabling commercial buyers to discover suppliers, manage quotations, and follow orders in real time.', 'Designed and developed the cross-platform mobile solution for iOS and Android.\n\nStructured product discovery, verified supplier access, and streamlined commercial checkout.\n\nEngineered instant order placement, delivery tracking, and procurement management.\n\nBuilt a consistent, responsive experience optimized for procurement officers and field operations.', 'Significantly accelerated order processing times for commercial and industrial commodity buyers.\n\nProvided buyers with full price transparency and reliable delivery timelines directly on mobile.\n\nExpanded Zarea\'s buyer network with thousands of active business procurement managers.', '["Cross-platform mobile app development","B2B checkout and order placement flows","Live delivery and procurement tracking","Supplier and product catalogue architecture","App Store and Play Store deployment"]', '["B2B Marketplace","Mobile App","Commodity Trading","Logistics Tracking"]', NULL, '[{"label":"Platforms","value":"iOS & Android"},{"label":"Categories","value":"Materials, Agri & Chemicals"},{"label":"Workflows","value":"Sourcing to Tracking"}]', 'published', 0, 0, NULL, 'Zarea — B2B Marketplace Mobile App Case Study | Amplipath', 'A cross-platform B2B marketplace enabling businesses to source construction materials, agricultural products, industrial chemicals and commodities with live delivery tracking.', NULL, 0, NULL, NULL, NULL, 17, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(19, 'Post Padel – AI Coaching Mobile App', 'postpadel', 'Sports Technology', 'An AI-powered padel coaching app that transforms match data into personalized improvement tips, performance insights and shareable coaching reports.', 'AI Coaching', 'Performance insights & shareable reports', 'An AI-powered padel coaching app that transforms match data into personalized improvement tips, performance insights, and shareable reports for players and trainers.', '/images/portfolio/postpadel.png', NULL, NULL, NULL, 'Post Padel helps padel players learn from every match or training session by recording performance, assessing individual shots and monitoring game development over time.\n\nMost amateur and competitive padel players lack affordable, continuous access to private coaching. Players needed an easy way to log shot breakdowns and receive actionable, data-backed guidance immediately after games.', 'Developed the AI-powered mobile coaching application for iOS and Android.\n\nEngineered algorithms that convert each player\'s logged match data into personalized coaching tips.\n\nGenerated weekly and monthly progress insights and exportable reports shareable with personal trainers.\n\nSupported panel-specific performance tracking across serves, volleys, smashes, forehands, backhands, bandejas, and viboras.', 'Successfully launched on iOS and Android with rapid adoption across padel clubs and competitive players.\n\nEmpowered players to pinpoint technique gaps and track measurable performance improvements over time.\n\nDelivered clean, professional exportable reports utilized by both players and professional trainers.', '["Mobile app development (iOS & Android)","AI integration & personalized coaching logic","Sports performance analytics engine","Exportable coaching reports generation","App Store & Play Store deployment"]', '["Mobile App Development","AI Integration","Sports Technology","App-Store Deployment"]', NULL, '[{"label":"Platforms","value":"iOS & Android"},{"label":"Shot Analysis","value":"Serves, Volleys, Smashes"},{"label":"Outputs","value":"Personalized Coaching Tips"}]', 'published', 0, 0, NULL, 'Post Padel – AI Coaching Mobile App Case Study | Amplipath', 'An AI-powered padel coaching app that transforms match data into personalized improvement tips, performance insights, and shareable reports for players and trainers.', NULL, 0, NULL, NULL, NULL, 18, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(20, 'Web Privacy AI – AI Data Removal App', 'webprivacy', 'Data Privacy and Cybersecurity', 'An AI-powered privacy application that finds personal information across data-broker websites and automates ongoing opt-out and removal requests.', '199+ Sites', 'Automated data broker opt-out & removal', 'An AI-powered privacy application that finds personal information across 199+ data-broker websites and automates ongoing opt-out and removal requests.', '/images/portfolio/webprivacy.jpg', NULL, NULL, NULL, 'Web Privacy AI helps individuals reduce unwanted exposure of their personal information across data-broker and people-search websites by replacing time-consuming manual removals with automated monitoring.\n\nPersonal names, phone numbers, addresses and family histories are routinely scraped and sold without permission. Opting out manually from hundreds of directories takes countless hours and requires perpetual follow-up.', 'Engineered an AI-driven data-removal mobile application for iOS and Android.\n\nBuilt scanning systems that search more than 199 data-broker and people-search websites.\n\nAutomated the submission of formal opt-out and personal data removal requests.\n\nImplemented continuous monitoring and detailed privacy reports to follow removal progress and catch reappearing records.', 'Eliminated dozens of hours of manual opt-out effort for users seeking online privacy.\n\nAchieved consistent data removal across leading people-search and data-broker networks.\n\nProvided ongoing peace of mind through real-time notifications and audit reports.', '["Mobile app development (iOS & Android)","AI automation & opt-out submission pipelines","Data-broker directory monitoring engine","Real-time privacy reporting dashboard","App Store & Play Store deployment"]', '["Mobile App Development","AI Automation","Cybersecurity","App-Store Deployment"]', NULL, '[{"label":"Scanned Registries","value":"199+ Data Brokers"},{"label":"Process","value":"Automated Opt-Out"},{"label":"Platforms","value":"iOS & Android"}]', 'published', 0, 0, NULL, 'Web Privacy AI – AI Data Removal App Case Study | Amplipath', 'An AI-powered privacy application that finds personal information across 199+ data-broker websites and automates ongoing opt-out and removal requests.', NULL, 0, NULL, NULL, NULL, 19, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(21, 'Osity – AI Learning and Discovery App', 'osity', 'Education Technology', 'An intelligent learning and discovery app that helps curious minds explore meaningful ideas, investigate topics and organize knowledge without endless scrolling.', 'Curated AI', 'Intentional discovery & knowledge vault', 'An intelligent learning and discovery app that helps curious minds explore meaningful ideas, investigate topics and organize knowledge without endless scrolling.', '/images/portfolio/osity.png', NULL, NULL, NULL, 'Osity is designed for lifelong learners and curious thinkers who want a calmer and more intentional way to discover information, combining daily ideas, words, quotes and topics with tools for deeper exploration.\n\nPassive algorithmic social feeds promote distraction and shallow attention. Osity sought to build a calm, intellectually stimulating haven where users can investigate big questions without doom-scrolling.', 'Built the AI-assisted learning and discovery application for iOS and Android.\n\nIntegrated daily ideas, words, quotes and topics with tools for deeper investigation.\n\nEngineered intelligent topic exploration allowing users to explore almost any subject.\n\nCreated a personal knowledge vault where users organize, curate, and revisit saved ideas.', 'Delivered a calming, focused alternative to passive content consumption.\n\nEnabled curious minds to investigate topics in depth and preserve intellectual insights effortlessly.\n\nEarned strong user acclaim for clean design, curated depth, and cognitive value.', '["Mobile app development (iOS & Android)","AI-assisted discovery & exploration engine","Knowledge vault architecture & organization","Minimalist UI/UX design","App Store & Play Store deployment"]', '["Mobile App Development","AI-Assisted Discovery","EdTech","App-Store Deployment"]', NULL, '[{"label":"Platforms","value":"iOS & Android"},{"label":"Philosophy","value":"Mindful Exploration"},{"label":"Feature","value":"Personal Knowledge Vault"}]', 'published', 0, 0, NULL, 'Osity – AI Learning and Discovery App Case Study | Amplipath', 'An intelligent learning and discovery app that helps curious minds explore meaningful ideas, investigate topics and organize knowledge without endless scrolling.', NULL, 0, NULL, NULL, NULL, 20, '2026-10-28 03:19:31', '2026-10-28 03:19:31'),
(22, 'Sgfmmm', 'sgfmmm', 'hbh', 'bn', '12', '434', 'fdfd', '/uploads/1793382173681_Screenshot_2026-10-14_225443.png', NULL, NULL, NULL, 'nvb', 'nvn', 'bnnb', '[]', '[]', '[]', '[{"label":"4","value":"4"}]', 'published', 0, 1, '2026-10-30 17:44:39', 'Sgfmmm Case Study | Amplipath', 'nhb', 'mb', 0, 'nb', 'g', '/uploads/1793382244336_Screenshot_2026-10-18_064458.png', 0, '2026-10-30 17:44:11', '2026-10-30 17:44:39');
